WITH flattened_attrs AS (SELECT id, service, level, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['region'], 'direct') AS region_or_default FROM app_logs) SELECT id, level, latency_ms, status_code_high, region_or_default, COUNT(retry_count) OVER (PARTITION BY service) AS service_count_retry_count, ROW_NUMBER() OVER (PARTITION BY service ORDER BY latency_ms DESC, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY service ORDER BY retry_count DESC, id) AS seq_no_2 FROM flattened_attrs
